AssistantMessageToolRequest(name='create', tool_call_id='function-call-b3a73978-3cb2-4e50-8fb5-eae7513aad3f', arguments={'file_text': 'const { useState } = React;

const questions = [
  {
    id: 1,
    question: "Which of the following are statically typed languages?",
    helpText: "Static typing means types are checked at compile-time rather than run-time.",
    options: ["Java", "C++", "Python", "JavaScript"],
    correct: ["Java", "C++"]
  },
  {
    id: 2,
    question: "Which of these languages are commonly used for systems programming?",
    options: ["Rust", "C", "PHP", "Ruby"],
    correct: ["Rust", "C"]
  },
  {
    id: 3,
    question: "Which of these languages are primarily used for mobile app development?",
    options: ["Swift", "Kotlin", "Dart", "Assembly"],
    correct: ["Swift", "Kotlin", "Dart"]
  }
];

const CheckboxGroup = ({ options, selectedOptions, onChange }) => {
  return (
    <div className="checkbox-group">
      {options.map(option => (
        <label key={option} className={`checkbox-item ${selectedOptions.includes(option) ? 'selected' : ''}`}>
          <input
            type="checkbox"
            checked={selectedOptions.includes(option)}
            onChange={() => onChange(option)}
          />
          {option}
        </label>
      ))}
    </div>
  );
};

const Quiz = () => {
  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const handleCheckboxChange = (questionId, option) => {
    const currentAnswers = answers[questionId] || [];
    if (currentAnswers.includes(option)) {
      setAnswers({
        ...answers,
        [questionId]: currentAnswers.filter(a => a !== option)
      });
    } else {
      setAnswers({
        ...answers,
        [questionId]: [...currentAnswers, option]
      });
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  const calculateScore = () => {
    let score = 0;
    questions.forEach(q => {
      const userAnswers = answers[q.id] || [];
      const correctAnswers = q.correct;
      const isCorrect = userAnswers.length === correctAnswers.length && 
                        userAnswers.every(val => correctAnswers.includes(val));
      if (isCorrect) score++;
    });
    return score;
  };

  if (submitted) {
    return (
      <div className="results">
        <h2>Quiz Results</h2>
        <p>You scored {calculateScore()} out of {questions.length}!</p>
        <button className="submit-btn" onClick={() => { setSubmitted(false); setAnswers({}); }}>
          Try Again
        </button>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="quiz-container">
      <h1>CS Languages Quiz</h1>
      {questions.map(q => (
        <div key={q.id} className="form-field">
          <span className="question-text">{q.question}</span>
          {q.helpText && <span className="help-text">{q.helpText}</span>}
          <CheckboxGroup
            options={q.options}
            selectedOptions={answers[q.id] || []}
            onChange={(option) => handleCheckboxChange(q.id, option)}
          />
        </div>
      ))}
      <button type="submit" className="submit-btn">Submit Quiz</button>
    </form>
  );
};

const App = () => {
  return (
    <div>
      <Quiz />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
