', direction=None, fact=None, file_name='/workspace/sandbox/control/checkbox-group--framework-react--style-dark/google/gemini-3-flash-preview__s1/script.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='const { useState } = React;

const questions = [
  {
    id: 1,
    question: "Which of the following are statically typed languages?",
    helpText: "Static typing means types are checked at compile-time rather than run-time.",
    options: ["Java", "C++", "Python", "JavaScript"],
    correct: ["Java", "C++"]
  },
  {
    id: 2,
    question: "Which of these languages are commonly used for systems programming?",
    options: ["Rust", "C", "PHP", "Ruby"],
    correct: ["Rust", "C"]
  },
  {
    id: 3,
    question: "Which of these languages are primarily used for mobile app development?",
    options: ["Swift", "Kotlin", "Dart", "Assembly"],
    correct: ["Swift", "Kotlin", "Dart"]
  }
];

const CheckboxGroup = ({ options, selectedOptions, onChange }) => (
  <div className="checkbox-group">
    {options.map(option => (
      <label key={option} className={`checkbox-item ${selectedOptions.includes(option) ? 'selected' : ''}`}>
        <input
          type="checkbox"
          checked={selectedOptions.includes(option)}
          onChange={() => onChange(option)}
        />
        {option}
      </label>
    ))}
  </div>
);

const Question = ({ q, selectedOptions, onAnswerChange }) => (
  <div className="form-field">
    <span className="question-text">{q.question}</span>
    {q.helpText && <span className="help-text">{q.helpText}</span>}
    <CheckboxGroup
      options={q.options}
      selectedOptions={selectedOptions}
      onChange={onAnswerChange}
    />
  </div>
);

const Quiz = () => {
  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const handleAnswerChange = (questionId, option) => {
    const current = answers[questionId] || [];
    const updated = current.includes(option)
      ? current.filter(a => a !== option)
      : [...current, option];
    setAnswers({ ...answers, [questionId]: updated });
  };

  const calculateScore = () => {
    return questions.reduce((acc, q) => {
      const user = answers[q.id] || [];
      const isCorrect = user.length === q.correct.length && 
                        user.every(v => q.correct.includes(v)) &&
                        q.correct.every(v => user.includes(v));
      return acc + (isCorrect ? 1 : 0);
    }, 0);
  };

  if (submitted) {
    const score = calculateScore();
    return (
      <div className="results">
        <h2>Quiz Results</h2>
        <p>You scored <strong>{score}</strong> out of {questions.length}!</p>
        <button className="submit-btn" onClick={() => { setSubmitted(false); setAnswers({}); }}>
          Restart Quiz
        </button>
      </div>
    );
  }

  return (
    <form className="quiz-container" onSubmit={(e) => { e.preventDefault(); setSubmitted(true); }}>
      <h1>Computer Languages Quiz</h1>
      {questions.map(q => (
        <Question
          key={q.id}
          q={q}
          selectedOptions={answers[q.id] || []}
          onAnswerChange={(option) => handleAnswerChange(q.id, option)}
        />
      ))}
      <button type="submit" className="submit-btn">Submit Quiz</button>
    </form>
  );
};

const App = () => (
  <div className="app-wrapper">
    <Quiz />
  </div>
);

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
