:root {
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-primary: #f8fafc;
    --text-secondary: #94a3b8;
    --accent: #818cf8;
    --accent-hover: #6366f1;
    --border: #334155;
    --selected-bg: #312e81;
}

body {
    background-color: var(--bg-color);
    color: var(--text-primary);
    font-family: 'Inter', sans-serif;
    margin: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

#root {
    width: 100%;
    max-width: 600px;
    padding: 2rem;
}

.quiz-container {
    background-color: var(--card-bg);
    padding: 2.5rem;
    border-radius: 12px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

h1 {
    margin-top: 0;
    font-size: 1.8rem;
    color: var(--accent);
    text-align: center;
    margin-bottom: 2rem;
}

.form-field {
    margin-bottom: 2rem;
    display: flex;
    flex-direction: column;
}

.question-text {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.help-text {
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 1rem;
    font-style: italic;
}

.checkbox-group {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-item {
    display: flex;
    align-items: center;
    background-color: #2c2c2c;
    padding: 0.75rem 1rem;
    border-radius: 8px;
    cursor: pointer;
    transition: background-color 0.2s, border-color 0.2s;
    border: 1px solid transparent;
}

.checkbox-item:hover {
    background-color: #383838;
}

.checkbox-item.selected {
    border-color: var(--accent);
    background-color: #3d2d52;
}

.checkbox-item input {
    margin-right: 0.75rem;
    accent-color: var(--accent);
    cursor: pointer;
}

.submit-btn {
    width: 100%;
    padding: 1rem;
    background-color: var(--accent);
    color: #000;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: bold;
    cursor: pointer;
    transition: background-color 0.2s;
    margin-top: 1rem;
}

.submit-btn:hover {
    background-color: var(--accent-hover);
}

.results {
    margin-top: 2rem;
    padding: 1.5rem;
    background-color: #2c2c2c;
    border-radius: 8px;
    text-align: center;
}

.results h2 {
    color: var(--accent);
    margin-top: 0;
}
