           type="checkbox"
           checked={selectedOptions.includes(option)}
           onChange={() => onChange(option)}
         />
         {option}
       </label>
     ))}
   </div>
 );

 const Question = ({ q, selectedOptions, onAnswerChange }) => (
   <div className="form-field">
     <span className="question-text">{q.question}</span>
     {q.helpText && <span className="help-text">{q.helpText}</span>}
     <CheckboxGroup
       options={q.options}
       selectedOptions={selectedOptions}
       onChange={onAnswerChange}
     />
   </div>
 );

 const Quiz = () => {
   const [answers, setAnswers] = useState({});
   const [submitted, setSubmitted] = useState(false);

   const handleAnswerChange = (questionId, option) => {
     const current = answers[questionId] || [];
     const updated = current.includes(option)
       ? current.filter(a => a !== option)
       : [...current, option];
     setAnswers({ ...answers, [questionId]: updated });
   };

   const calculateScore = () => {
     return questions.reduce((acc, q) => {
       const user = answers[q.id] || [];
       const isCorrect = user.length === q.correct.length && 
                         user.every(v => q.correct.includes(v)) &&
                         q.correct.every(v => user.includes(v));
