       {questions.map(q => (
         <Question
           key={q.id}
           q={q}
           selectedOptions={answers[q.id] || []}
           onAnswerChange={(option) => handleAnswerChange(q.id, option)}
         />
       ))}
       <button type="submit" className="submit-btn">Submit Quiz</button>
     </form>
   );
 };

 const App = () => (
   <div className="app-wrapper">
     <Quiz />
   </div>
 );

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<App />);

